 tools_path = str(root / 'tools')
 def loader_name(name, stem):
  return (name in (stem, stem + '.py', stem + '.pyc')
   or name.startswith(stem + '.') and name.endswith(('.so', '.pyd')))
 def source_roster(path):
  row = source.row_index.get(str(path))
